1	/**
2	 * Modal contextual de CONTEUDO da etiqueta — abre ao clicar PackageOpen num item bipado.
3	 *
4	 * Serve SO PRA MEXER NO CONTEUDO INTERNO do container (saldo disponivel).
5	 * Movimentacao do container inteiro (saida/entrada) vai pelos botoes do rodape
6	 * do Scanner — esses chamam bipar_etiqueta(saida/entrada) e NAO alteram saldo.
7	 *
8	 * 2 acoes:
9	 *   - Retirar avulso (laranja)  → bipar_retirada_avulsa(uid, qtd)  · saldo −N
10	 *   - Adicionar avulso (azul)   → bipar_devolucao_avulsa(uid, qtd) · saldo +N
11	 *
12	 * Input livre + presets (1, 5, 10, Tudo) — escolhe o que for mais rapido.
13	 */
14	import { useState, useEffect } from "react";
15	import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
16	import { Button } from "@/shared/ui/button";
17	import { Input } from "@/shared/ui/input";
18	import { Label } from "@/shared/ui/label";
19	import { PackageMinus, PackageOpen, PackagePlus, Loader2, X, ArrowDownUp } from "lucide-react";
20	import { cn } from "@/shared/lib/utils";
21	
22	export interface EtiquetaContext {
23	  uid: string;
24	  produto_nome: string;
25	  tipo_embalagem: string | null; // "caixa", "saco", "balde", "granel"
26	  embalagem_nome: string | null; // unidade interna: "un", "kg", "g", "l", "ml"
27	  quantidade_interna: number;
28	  quantidade_disponivel: number;
29	  status?: string | null;
30	  foto_url?: string | null;
31	  lote_codigo?: string | null;
32	}
33	
34	interface Props {
35	  isOpen: boolean;
36	  etiqueta: EtiquetaContext | null;
37	  onClose: () => void;
38	  /** Retirada parcial do conteudo — usa bipar_retirada_avulsa(uid, qtd).
39	      Movimentacao do CONTAINER inteiro (saida/entrada) NAO passa por aqui —
40	      vai pelo Scanner.tsx que chama bipar_etiqueta(saida/entrada) direto. */
41	  onSaidaAvulsa: (etiqueta: EtiquetaContext, qtd: number) => Promise<void> | void;
42	  /** Dispara adição avulsa — usa bipar_devolucao_avulsa(uid, qtd). Soma N unidades no container. */
43	  onAdicionarAvulsa?: (etiqueta: EtiquetaContext, qtd: number) => Promise<void> | void;
44	  loading?: boolean;
45	}
46	
47	const PRESET_VALUES = [1, 5, 10];
48	
49	export function SaidaAvulsaDialog({ isOpen, etiqueta, onClose, onSaidaAvulsa, onAdicionarAvulsa, loading = false }: Props) {
50	  const [modo, setModo] = useState<"escolher" | "retirar" | "adicionar">("escolher");
51	  const [quantidade, setQuantidade] = useState<string>("1");
52	
53	  // Reset ao abrir
54	  useEffect(() => {
55	    if (isOpen) {
56	      setModo("escolher");
57	      setQuantidade("1");
58	    }
59	  }, [isOpen, etiqueta?.uid]);
60	
61	  if (!etiqueta) return null;
62	
63	  const disponivel = etiqueta.quantidade_disponivel ?? etiqueta.quantidade_interna;
64	  const capacidade = etiqueta.quantidade_interna;
65	  const isAberta = disponivel < capacidade;
66	  const isVazia = disponivel <= 0;
67	  const cabe = capacidade - disponivel; // quanto ainda cabe adicionar
68	  const unidade = (etiqueta.embalagem_nome || "un").toLowerCase();
69	  const tipo = (etiqueta.tipo_embalagem || "caixa").toLowerCase();
70	
71	  // Modo retirar limita pelo disponivel; modo adicionar limita pelo espaco que cabe
72	  const limite = modo === "adicionar" ? cabe : disponivel;
73	  const qtdNum = Math.max(0, Math.min(limite, Number(quantidade) || 0));
74	  const qtdValida = qtdNum > 0 && qtdNum <= limite;
75	
76	  const handleConfirmAvulso = async () => {
77	    if (!qtdValida) return;
78	    if (modo === "adicionar" && onAdicionarAvulsa) {
79	      await onAdicionarAvulsa(etiqueta, qtdNum);
80	    } else {
81	      await onSaidaAvulsa(etiqueta, qtdNum);
82	    }
83	  };
84	
85	  return (
86	    <Dialog open={isOpen} onOpenChange={(o) => !o && !loading && onClose()}>
87	      <DialogContent className="max-w-md p-0 overflow-hidden rounded-3xl">
88	        {/* Header com saldo */}
89	        <div className={cn(
90	          "px-6 py-5 text-white",
91	          isAberta ? "bg-gradient-to-br from-orange-500 to-orange-600" : "bg-gradient-to-br from-[#57715B] to-[#4A614E]"
92	        )}>
93	          <div className="flex items-start justify-between gap-3">
94	            <div className="flex-1 min-w-0">
95	              <div className="flex items-center gap-2 mb-1">
96	                {isAberta ? <PackageOpen className="w-5 h-5" /> : <PackageMinus className="w-5 h-5" />}
97	                <DialogTitle className="text-base font-bold uppercase tracking-wider">
98	                  {isAberta ? "Container Aberto" : "Saída de Etiqueta"}
99	                </DialogTitle>
100	              </div>
101	              <p className="text-sm opacity-90 truncate">{etiqueta.produto_nome}</p>
102	              {etiqueta.lote_codigo && (
103	                <p className="text-[11px] opacity-75 font-mono mt-0.5">Lote {etiqueta.lote_codigo}</p>
104	              )}
105	            </div>
106	            <Button
107	              variant="ghost"
108	              size="icon"
109	              onClick={onClose}
110	              disabled={loading}
111	              className="text-white hover:bg-white/20 rounded-2xl h-9 w-9 flex-shrink-0"
112	            >
113	              <X className="w-4 h-4" />
114	            </Button>
115	          </div>
116	
117	          {/* Saldo grande */}
118	          <div className="mt-4 flex items-baseline gap-2">
119	            <span className="text-4xl font-black tabular-nums">{disponivel}</span>
120	            <span className="text-lg font-semibold opacity-80">{unidade}</span>
121	            {isAberta && (
122	              <span className="text-xs opacity-70 ml-auto">
123	                de {capacidade} ({capacidade - disponivel} retirados)
124	              </span>
125	            )}
126	            {!isAberta && (
127	              <span className="text-xs opacity-70 ml-auto">cheio · 1 {tipo}</span>
128	            )}
129	          </div>
130	        </div>
131	
132	        {/* Body — escolha ou input */}
133	        <div className="p-5 space-y-4">
134	          {modo === "escolher" ? (
135	            <>
136	              {/* Explicacao do contexto: este modal eh SO PRA MEXER NO CONTEUDO interno.
137	                  Saida/Entrada do container inteiro vai pelos botoes do rodape do Scanner
138	                  ("Confirmar Saidas/Entradas") — eles nao alteram o saldo. */}
139	              <div className="p-3 rounded-xl bg-amber-50 dark:bg-amber-950/20 border border-amber-200 dark:border-amber-800 text-xs">
140	                <p className="text-amber-900 dark:text-amber-200">
141	                  <b>Mexer no conteúdo</b> do container. Para movimentar o container inteiro
142	                  (saída/entrada), use os botões do rodapé — saldo fica intacto.
143	                </p>
144	              </div>
145	
146	              {/* Retirar avulso — primario, age sobre saldo interno */}
147	              <button
148	                onClick={() => setModo("retirar")}
149	                disabled={loading || isVazia}
150	                className={cn(
151	                  "w-full p-5 rounded-2xl border-2 transition-all text-left",
152	                  "border-orange-300/40 hover:border-orange-400 hover:bg-orange-50/50 dark:hover:bg-orange-950/20",
153	                  "disabled:opacity-50 disabled:cursor-not-allowed"
154	                )}
155	              >
156	                <div className="flex items-center gap-3">
157	                  <div className="h-12 w-12 rounded-2xl bg-orange-500/10 flex items-center justify-center">
158	                    <PackageOpen className="w-5 h-5 text-orange-600" />
159	                  </div>
160	                  <div className="flex-1 min-w-0">
161	                    <p className="font-bold text-orange-700 dark:text-orange-400 text-base">Retirar avulso</p>
162	                    <p className="text-xs text-muted-foreground">
163	                      {isVazia ? "Container vazio" : `Tirar N de dentro · saldo atual ${disponivel} ${unidade}`}
164	                    </p>
165	                  </div>
166	                </div>
167	              </button>
168	
169	              {/* Adicionar avulso — só aparece se houver espaço */}
170	              {onAdicionarAvulsa && cabe > 0 && (
171	                <button
172	                  onClick={() => setModo("adicionar")}
173	                  disabled={loading}
174	                  className={cn(
175	                    "w-full p-5 rounded-2xl border-2 transition-all text-left",
176	                    "border-blue-300/40 hover:border-blue-400 hover:bg-blue-50/50 dark:hover:bg-blue-950/20",
177	                    "disabled:opacity-50 disabled:cursor-not-allowed"
178	                  )}
179	                >
180	                  <div className="flex items-center gap-3">
181	                    <div className="h-12 w-12 rounded-2xl bg-blue-500/10 flex items-center justify-center">
182	                      <PackagePlus className="w-5 h-5 text-blue-600" />
183	                    </div>
184	                    <div className="flex-1 min-w-0">
185	                      <p className="font-bold text-blue-700 dark:text-blue-400 text-base">Adicionar avulso</p>
186	                      <p className="text-xs text-muted-foreground">
187	                        Colocar N de volta · cabe +{cabe} {unidade}
188	                      </p>
189	                    </div>
190	                  </div>
191	                </button>
192	              )}
193	            </>
194	          ) : (
195	            <>
196	              {/* Modo retirar OU adicionar — input + presets */}
197	              <div className="space-y-2">
198	                <Label className="text-xs uppercase font-bold text-muted-foreground tracking-wider">
199	                  Quantidade a {modo === "adicionar" ? "adicionar" : "retirar"}
200	                </Label>
201	                <div className="flex items-center gap-2">
202	                  <Input
203	                    type="number"
204	                    min={1}
205	                    max={limite}
206	                    value={quantidade}
207	                    onChange={(e) => setQuantidade(e.target.value)}
208	                    onKeyDown={(e) => e.key === "Enter" && qtdValida && handleConfirmAvulso()}
209	                    className="h-14 text-center text-2xl font-black rounded-2xl"
210	                    autoFocus
211	                  />
212	                  <span className="text-base font-bold text-muted-foreground min-w-[36px]">{unidade}</span>
213	                </div>
214	                <p className="text-[11px] text-muted-foreground text-center">
215	                  {modo === "adicionar"
216	                    ? `cabe no máximo ${cabe} ${unidade} (espaço livre)`
217	                    : `máximo ${disponivel} ${unidade} disponíveis`}
218	                </p>
219	              </div>
220	
221	              {/* Presets */}
222	              <div className="grid grid-cols-4 gap-2">
223	                {PRESET_VALUES.filter((v) => v <= limite).map((v) => (
224	                  <Button
225	                    key={v}
226	                    variant="outline"
227	                    onClick={() => setQuantidade(String(v))}
228	                    disabled={loading}
229	                    className={cn(
230	                      "h-12 rounded-xl font-bold",
231	                      Number(quantidade) === v && "bg-[#57715B]/10 border-[#57715B] text-[#57715B]"
232	                    )}
233	                  >
234	                    {v}
235	                  </Button>
236	                ))}
237	                <Button
238	                  variant="outline"
239	                  onClick={() => setQuantidade(String(limite))}
240	                  disabled={loading}
241	                  className={cn(
242	                    "h-12 rounded-xl font-bold",
243	                    Number(quantidade) === limite && "bg-[#57715B]/10 border-[#57715B] text-[#57715B]"
244	                  )}
245	                >
246	                  Tudo
247	                </Button>
248	              </div>
249	
250	              {/* Preview do impacto */}
251	              {qtdValida && (
252	                <div className="p-3 rounded-xl bg-muted/50 text-xs text-center">
253	                  Após {modo === "adicionar" ? "adicionar" : "retirar"}: container terá{" "}
254	                  <b className="text-[#57715B]">
255	                    {modo === "adicionar" ? disponivel + qtdNum : disponivel - qtdNum} {unidade}
256	                  </b>
257	                  {modo === "retirar" && disponivel - qtdNum === 0 && (
258	                    <span className="block mt-1 text-red-600 font-bold">→ etiqueta será consumida</span>
259	                  )}
260	                  {modo === "adicionar" && disponivel + qtdNum === capacidade && (
261	                    <span className="block mt-1 text-emerald-600 font-bold">→ etiqueta volta a cheia</span>
262	                  )}
263	                </div>
264	              )}
265	
266	              {/* Ações */}
267	              <div className="flex gap-2 pt-1">
268	                <Button
269	                  variant="outline"
270	                  onClick={() => setModo("escolher")}
271	                  disabled={loading}
272	                  className="flex-1 h-12 rounded-xl"
273	                >
274	                  Voltar
275	                </Button>
276	                <Button
277	                  onClick={handleConfirmAvulso}
278	                  disabled={loading || !qtdValida}
279	                  className={cn(
280	                    "flex-1 h-12 rounded-xl text-white font-bold",
281	                    modo === "adicionar" ? "bg-blue-600 hover:bg-blue-700" : "bg-orange-600 hover:bg-orange-700"
282	                  )}
283	                >
284	                  {loading ? <Loader2 className="w-4 h-4 animate-spin" />
285	                    : `${modo === "adicionar" ? "Adicionar" : "Retirar"} ${qtdNum} ${unidade}`}
286	                </Button>
287	              </div>
288	            </>
289	          )}
290	        </div>
291	      </DialogContent>
292	    </Dialog>
293	  );
294	}
