/**
 * Modal contextual de CONTEUDO da etiqueta — abre ao clicar PackageOpen num item bipado.
 *
 * Serve SO PRA MEXER NO CONTEUDO INTERNO do container (saldo disponivel).
 * Movimentacao do container inteiro (saida/entrada) vai pelos botoes do rodape
 * do Scanner — esses chamam bipar_etiqueta(saida/entrada) e NAO alteram saldo.
 *
 * 2 acoes:
 *   - Retirar avulso (laranja)  → bipar_retirada_avulsa(uid, qtd)  · saldo −N
 *   - Adicionar avulso (azul)   → bipar_devolucao_avulsa(uid, qtd) · saldo +N
 *
 * Input livre + presets (1, 5, 10, Tudo) — escolhe o que for mais rapido.
 */
import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Label } from "@/shared/ui/label";
import { PackageMinus, PackageOpen, PackagePlus, Loader2, X, ArrowDownUp } from "lucide-react";
import { cn } from "@/shared/lib/utils";

export interface EtiquetaContext {
  uid: string;
  produto_nome: string;
  tipo_embalagem: string | null; // "caixa", "saco", "balde", "granel"
  embalagem_nome: string | null; // unidade interna: "un", "kg", "g", "l", "ml"
  quantidade_interna: number;
  quantidade_disponivel: number;
  status?: string | null;
  foto_url?: string | null;
  lote_codigo?: string | null;
}

interface Props {
  isOpen: boolean;
  etiqueta: EtiquetaContext | null;
  onClose: () => void;
  /** Retirada parcial do conteudo — usa bipar_retirada_avulsa(uid, qtd).
      Movimentacao do CONTAINER inteiro (saida/entrada) NAO passa por aqui —
      vai pelo Scanner.tsx que chama bipar_etiqueta(saida/entrada) direto. */
  onSaidaAvulsa: (etiqueta: EtiquetaContext, qtd: number) => Promise<void> | void;
  /** Dispara adição avulsa — usa bipar_devolucao_avulsa(uid, qtd). Soma N unidades no container. */
  onAdicionarAvulsa?: (etiqueta: EtiquetaContext, qtd: number) => Promise<void> | void;
  loading?: boolean;
}

const PRESET_VALUES = [1, 5, 10];

export function SaidaAvulsaDialog({ isOpen, etiqueta, onClose, onSaidaAvulsa, onAdicionarAvulsa, loading = false }: Props) {
  const [modo, setModo] = useState<"escolher" | "retirar" | "adicionar">("escolher");
  const [quantidade, setQuantidade] = useState<string>("1");

  // Reset ao abrir
  useEffect(() => {
    if (isOpen) {
      setModo("escolher");
      setQuantidade("1");
    }
  }, [isOpen, etiqueta?.uid]);

  if (!etiqueta) return null;

  const disponivel = etiqueta.quantidade_disponivel ?? etiqueta.quantidade_interna;
  const capacidade = etiqueta.quantidade_interna;
  const isAberta = disponivel < capacidade;
  const isVazia = disponivel <= 0;
  const cabe = capacidade - disponivel; // quanto ainda cabe adicionar
  const unidade = (etiqueta.embalagem_nome || "un").toLowerCase();
  const tipo = (etiqueta.tipo_embalagem || "caixa").toLowerCase();

  // Modo retirar limita pelo disponivel; modo adicionar limita pelo espaco que cabe
  const limite = modo === "adicionar" ? cabe : disponivel;
  const qtdNum = Math.max(0, Math.min(limite, Number(quantidade) || 0));
  const qtdValida = qtdNum > 0 && qtdNum <= limite;

  const handleConfirmAvulso = async () => {
    if (!qtdValida) return;
    if (modo === "adicionar" && onAdicionarAvulsa) {
      await onAdicionarAvulsa(etiqueta, qtdNum);
    } else {
      await onSaidaAvulsa(etiqueta, qtdNum);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={(o) => !o && !loading && onClose()}>
      <DialogContent className="max-w-md p-0 overflow-hidden rounded-3xl">
        {/* Header com saldo */}
        <div className={cn(
          "px-6 py-5 text-white",
          isAberta ? "bg-gradient-to-br from-orange-500 to-orange-600" : "bg-gradient-to-br from-[#57715B] to-[#4A614E]"
        )}>
          <div className="flex items-start justify-between gap-3">
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 mb-1">
                {isAberta ? <PackageOpen className="w-5 h-5" /> : <PackageMinus className="w-5 h-5" />}
                <DialogTitle className="text-base font-bold uppercase tracking-wider">
                  {isAberta ? "Container Aberto" : "Saída de Etiqueta"}
                </DialogTitle>
              </div>
              <p className="text-sm opacity-90 truncate">{etiqueta.produto_nome}</p>
              {etiqueta.lote_codigo && (
                <p className="text-[11px] opacity-75 font-mono mt-0.5">Lote {etiqueta.lote_codigo}</p>
              )}
            </div>
            <Button
              variant="ghost"
              size="icon"
              onClick={onClose}
              disabled={loading}
              className="text-white hover:bg-white/20 rounded-2xl h-9 w-9 flex-shrink-0"
            >
              <X className="w-4 h-4" />
            </Button>
          </div>

          {/* Saldo grande */}
          <div className="mt-4 flex items-baseline gap-2">
            <span className="text-4xl font-black tabular-nums">{disponivel}</span>
            <span className="text-lg font-semibold opacity-80">{unidade}</span>
            {isAberta && (
              <span className="text-xs opacity-70 ml-auto">
                de {capacidade} ({capacidade - disponivel} retirados)
              </span>
            )}
            {!isAberta && (
              <span className="text-xs opacity-70 ml-auto">cheio · 1 {tipo}</span>
            )}
          </div>
        </div>

        {/* Body — escolha ou input */}
        <div className="p-5 space-y-4">
          {modo === "escolher" ? (
            <>
              {/* Explicacao do contexto: este modal eh SO PRA MEXER NO CONTEUDO interno.
                  Saida/Entrada do container inteiro vai pelos botoes do rodape do Scanner
                  ("Confirmar Saidas/Entradas") — eles nao alteram o saldo. */}
              <div className="p-3 rounded-xl bg-amber-50 dark:bg-amber-950/20 border border-amber-200 dark:border-amber-800 text-xs">
                <p className="text-amber-900 dark:text-amber-200">
                  <b>Mexer no conteúdo</b> do container. Para movimentar o container inteiro
                  (saída/entrada), use os botões do rodapé — saldo fica intacto.
                </p>
              </div>

              {/* Retirar avulso — primario, age sobre saldo interno */}
              <button
                onClick={() => setModo("retirar")}
                disabled={loading || isVazia}
                className={cn(
                  "w-full p-5 rounded-2xl border-2 transition-all text-left",
                  "border-orange-300/40 hover:border-orange-400 hover:bg-orange-50/50 dark:hover:bg-orange-950/20",
                  "disabled:opacity-50 disabled:cursor-not-allowed"
                )}
              >
                <div className="flex items-center gap-3">
                  <div className="h-12 w-12 rounded-2xl bg-orange-500/10 flex items-center justify-center">
                    <PackageOpen className="w-5 h-5 text-orange-600" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="font-bold text-orange-700 dark:text-orange-400 text-base">Retirar avulso</p>
                    <p className="text-xs text-muted-foreground">
                      {isVazia ? "Container vazio" : `Tirar N de dentro · saldo atual ${disponivel} ${unidade}`}
                    </p>
                  </div>
                </div>
              </button>

              {/* Adicionar avulso — só aparece se houver espaço */}
              {onAdicionarAvulsa && cabe > 0 && (
                <button
                  onClick={() => setModo("adicionar")}
                  disabled={loading}
                  className={cn(
                    "w-full p-5 rounded-2xl border-2 transition-all text-left",
                    "border-blue-300/40 hover:border-blue-400 hover:bg-blue-50/50 dark:hover:bg-blue-950/20",
                    "disabled:opacity-50 disabled:cursor-not-allowed"
                  )}
                >
                  <div className="flex items-center gap-3">
                    <div className="h-12 w-12 rounded-2xl bg-blue-500/10 flex items-center justify-center">
                      <PackagePlus className="w-5 h-5 text-blue-600" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="font-bold text-blue-700 dark:text-blue-400 text-base">Adicionar avulso</p>
                      <p className="text-xs text-muted-foreground">
                        Colocar N de volta · cabe +{cabe} {unidade}
                      </p>
                    </div>
                  </div>
                </button>
              )}
            </>
          ) : (
            <>
              {/* Modo retirar OU adicionar — input + presets */}
              <div className="space-y-2">
                <Label className="text-xs uppercase font-bold text-muted-foreground tracking-wider">
                  Quantidade a {modo === "adicionar" ? "adicionar" : "retirar"}
                </Label>
                <div className="flex items-center gap-2">
                  <Input
                    type="number"
                    min={1}
                    max={limite}
                    value={quantidade}
                    onChange={(e) => setQuantidade(e.target.value)}
                    onKeyDown={(e) => e.key === "Enter" && qtdValida && handleConfirmAvulso()}
                    className="h-14 text-center text-2xl font-black rounded-2xl"
                    autoFocus
                  />
                  <span className="text-base font-bold text-muted-foreground min-w-[36px]">{unidade}</span>
                </div>
                <p className="text-[11px] text-muted-foreground text-center">
                  {modo === "adicionar"
                    ? `cabe no máximo ${cabe} ${unidade} (espaço livre)`
                    : `máximo ${disponivel} ${unidade} disponíveis`}
                </p>
              </div>

              {/* Presets */}
              <div className="grid grid-cols-4 gap-2">
                {PRESET_VALUES.filter((v) => v <= limite).map((v) => (
                  <Button
                    key={v}
                    variant="outline"
                    onClick={() => setQuantidade(String(v))}
                    disabled={loading}
                    className={cn(
                      "h-12 rounded-xl font-bold",
                      Number(quantidade) === v && "bg-[#57715B]/10 border-[#57715B] text-[#57715B]"
                    )}
                  >
                    {v}
                  </Button>
                ))}
                <Button
                  variant="outline"
                  onClick={() => setQuantidade(String(limite))}
                  disabled={loading}
                  className={cn(
                    "h-12 rounded-xl font-bold",
                    Number(quantidade) === limite && "bg-[#57715B]/10 border-[#57715B] text-[#57715B]"
                  )}
                >
                  Tudo
                </Button>
              </div>

              {/* Preview do impacto */}
              {qtdValida && (
                <div className="p-3 rounded-xl bg-muted/50 text-xs text-center">
                  Após {modo === "adicionar" ? "adicionar" : "retirar"}: container terá{" "}
                  <b className="text-[#57715B]">
                    {modo === "adicionar" ? disponivel + qtdNum : disponivel - qtdNum} {unidade}
                  </b>
                  {modo === "retirar" && disponivel - qtdNum === 0 && (
                    <span className="block mt-1 text-red-600 font-bold">→ etiqueta será consumida</span>
                  )}
                  {modo === "adicionar" && disponivel + qtdNum === capacidade && (
                    <span className="block mt-1 text-emerald-600 font-bold">→ etiqueta volta a cheia</span>
                  )}
                </div>
              )}

              {/* Ações */}
              <div className="flex gap-2 pt-1">
                <Button
                  variant="outline"
                  onClick={() => setModo("escolher")}
                  disabled={loading}
                  className="flex-1 h-12 rounded-xl"
                >
                  Voltar
                </Button>
                <Button
                  onClick={handleConfirmAvulso}
                  disabled={loading || !qtdValida}
                  className={cn(
                    "flex-1 h-12 rounded-xl text-white font-bold",
                    modo === "adicionar" ? "bg-blue-600 hover:bg-blue-700" : "bg-orange-600 hover:bg-orange-700"
                  )}
                >
                  {loading ? <Loader2 className="w-4 h-4 animate-spin" />
                    : `${modo === "adicionar" ? "Adicionar" : "Retirar"} ${qtdNum} ${unidade}`}
                </Button>
              </div>
            </>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

