-- Fix pós-QA da expositora:
-- 1) mover_para_expositora: baixa FIFO em estoque_lotes (com guard skip_lote_reconcile)
--    pra não desincronizar lotes ↔ estoque (reconciliador reverteria a baixa).
-- 2) bipar_etiqueta: mensagem de re-bip na exposição contém "ja esta com status"
--    (frontend classifica como duplicado/âmbar, não erro).

CREATE OR REPLACE FUNCTION public.mover_para_expositora(
  p_produto_master_id integer,
  p_loja_id           integer,
  p_quantidade        numeric,
  p_observacoes       text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_estoque_anterior numeric;
  v_estoque_novo     numeric;
  v_expositora       numeric;
  v_alertas          jsonb := '[]'::jsonb;
  v_restante         numeric;
  v_baixa            numeric;
  r                  RECORD;
BEGIN
  IF p_quantidade IS NULL OR p_quantidade <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Quantidade deve ser maior que zero');
  END IF;
  IF p_loja_id IS NULL OR p_loja_id = 1 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Expositora é por loja — fábrica não tem vitrine');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.produtos_master WHERE id = p_produto_master_id AND ativo = true) THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Produto não encontrado ou inativo');
  END IF;

  SELECT quantidade_atual INTO v_estoque_anterior
    FROM public.estoque
   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id
   FOR UPDATE;

  v_estoque_anterior := COALESCE(v_estoque_anterior, 0);
  v_estoque_novo     := v_estoque_anterior - p_quantidade;

  IF v_estoque_novo < 0 THEN
    v_alertas := v_alertas || jsonb_build_array(
      format('Estoque da câmara ficou negativo (%s) — confira a contagem', v_estoque_novo));
  END IF;

  -- Baixa FIFO em estoque_lotes (validade mais próxima primeiro) pra manter
  -- lotes ↔ estoque em sincronia. Sem isso, a próxima edição direta de
  -- estoque_lotes dispararia sync_estoque_from_lotes, que REVERTERIA esta
  -- baixa via 'sync_lote_auto' (produto contado em dobro: câmara + vitrine).
  PERFORM set_config('app.skip_lote_reconcile', '1', true);
  v_restante := p_quantidade;
  FOR r IN
    SELECT el.id, el.quantidade
      FROM public.estoque_lotes el
      LEFT JOIN public.lotes l ON l.id = el.lote_id
     WHERE el.produto_id = p_produto_master_id
       AND el.loja_id = p_loja_id
       AND el.quantidade > 0
     ORDER BY l.data_validade NULLS LAST, el.id
     FOR UPDATE OF el
  LOOP
    EXIT WHEN v_restante <= 0;
    v_baixa := LEAST(r.quantidade, v_restante);
    UPDATE public.estoque_lotes SET quantidade = quantidade - v_baixa WHERE id = r.id;
    v_restante := v_restante - v_baixa;
  END LOOP;

  INSERT INTO public.movimentacoes (
    produto_master_id, tipo_movimentacao, quantidade,
    quantidade_anterior, quantidade_nova, motivo, observacoes,
    data_movimentacao, loja_id
  ) VALUES (
    p_produto_master_id, 'saida', p_quantidade,
    v_estoque_anterior, v_estoque_novo, 'exposicao',
    COALESCE(p_observacoes, 'Movido para expositora'),
    now(), p_loja_id
  );

  SELECT quantidade INTO v_expositora
    FROM public.expositora_estoque
   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id;

  RETURN jsonb_build_object(
    'ok', true,
    'estoque_anterior',  v_estoque_anterior,
    'estoque_novo',      v_estoque_novo,
    'expositora_saldo',  COALESCE(v_expositora, 0),
    'alertas',           v_alertas
  );
END;
$$;

-- 2) Só a mensagem do re-bip muda; resto idêntico à versão aplicada em expositora_pronta_entrega.
DO $do$
DECLARE
  v_def text;
BEGIN
  SELECT pg_get_functiondef(p.oid) INTO v_def
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = 'bipar_etiqueta';

  v_def := replace(v_def,
    'esta com status "%s" — nao pode ir pra expositora',
    'ja esta com status "%s" — nao pode ir pra expositora');

  EXECUTE v_def;
END
$do$;

BEGIN;

CREATE TEMP TABLE _smoke3 AS
SELECT el.produto_id AS produto_master_id, el.loja_id,
       SUM(el.quantidade) AS lotes_antes,
       (SELECT quantidade_atual FROM estoque WHERE produto_master_id = el.produto_id AND loja_id = el.loja_id) AS estoque_antes
FROM estoque_lotes el
JOIN produtos_master pm ON pm.id = el.produto_id AND pm.ativo = true
WHERE el.quantidade >= 3 AND el.loja_id <> 1
GROUP BY el.produto_id, el.loja_id
LIMIT 1;

SELECT (SELECT COUNT(*) FROM _smoke3) AS achou_alvo;

SELECT public.mover_para_expositora(s.produto_master_id, s.loja_id, 2, 'smoke fifo') AS rpc FROM _smoke3 s;

SELECT jsonb_build_object(
  'alvo', (SELECT row_to_json(s) FROM _smoke3 s),
  'lotes_apos', (SELECT SUM(el.quantidade) FROM estoque_lotes el JOIN _smoke3 s ON el.produto_id = s.produto_master_id AND el.loja_id = s.loja_id),
  'estoque_apos', (SELECT e.quantidade_atual FROM estoque e JOIN _smoke3 s ON e.produto_master_id = s.produto_master_id AND e.loja_id = s.loja_id),
  'expositora', (SELECT x.quantidade FROM expositora_estoque x JOIN _smoke3 s ON x.produto_master_id = s.produto_master_id AND x.loja_id = s.loja_id),
  'fantasma_sync_lote_auto', (SELECT COUNT(*) FROM movimentacoes m JOIN _smoke3 s ON m.produto_master_id = s.produto_master_id AND m.loja_id = s.loja_id
                              WHERE m.motivo = 'sync_lote_auto' AND m.data_movimentacao > now() - interval '1 minute')
) AS resultado;

ROLLBACK;

