SELECT jsonb_build_object(
  'token_status', (
    SELECT jsonb_build_object(
      'valido', (expires_at > now()),
      'expira_em', to_char(expires_at AT TIME ZONE 'America/Sao_Paulo', 'DD/MM HH24:MI'),
      'renovado_em', to_char(refreshed_at AT TIME ZONE 'America/Sao_Paulo', 'DD/MM HH24:MI'),
      'refresh_count', refresh_count,
      'erro', last_error
    ) FROM degust_auth WHERE id = 1
  ),
  'metas_vendas_existe', (SELECT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name='metas_vendas' AND table_schema='public')),
  'metas_configuradas', (SELECT COUNT(*) FROM metas_vendas),
  'ultimo_sync', (
    SELECT to_char(MAX(synced_at) AT TIME ZONE 'America/Sao_Paulo', 'DD/MM HH24:MI')
    FROM degust_vendas_diarias
  ),
  'dias_com_venda_hoje', (
    SELECT COUNT(DISTINCT loja_id) FROM degust_vendas_diarias WHERE data = CURRENT_DATE
  ),
  'dias_com_venda_ontem', (
    SELECT COUNT(DISTINCT loja_id) FROM degust_vendas_diarias WHERE data = CURRENT_DATE - 1
  )
) AS status;

