      {items.length === 0 ? (
        <p
          className="mt-1 flex items-center gap-1.5 font-momma text-[clamp(0.75rem,0.85vw,1.5rem)] font-medium text-emerald-600"
          data-testid="tv-col-critical-empty"
        >
          <CheckCircle2 className="h-[1em] w-[1em] shrink-0" aria-hidden />
          estoque ok
        </p>
      ) : (
        <ul className="mt-1 space-y-1">
          {visible.map((item) => {
            const zerado = item.severity === 'zerado';
            return (
              <li
                key={item.nome}
                className="flex items-center gap-1.5 font-momma text-[clamp(0.75rem,0.85vw,1.5rem)] leading-tight"
                data-testid="tv-col-critical-item"
                data-severity={item.severity}
              >
                {zerado ? (
                  <OctagonAlert
                    className="h-[1em] w-[1em] shrink-0 text-red-500"
                    aria-hidden
                  />
                ) : (
                  <TriangleAlert
                    className="h-[1em] w-[1em] shrink-0 text-amber-500"
                    aria-hidden
                  />
                )}
                <span className="min-w-0 flex-1 truncate font-medium text-[#2D362E]">
                  {item.nome}
                </span>
                <span
                  className={`shrink-0 font-medium tabular-nums ${
                    zerado ? 'text-red-600' : 'text-amber-600'
                  }`}
                >
                  {zerado
                    ? '0 un'
                    : `${formatQty(item.quantidade)} de ${formatQty(item.minima)} mín`}
                </span>
              </li>
            );
          })}
          {overflow > 0 && (
            <li
              className="font-momma text-[clamp(0.6875rem,0.75vw,1.375rem)] text-[#7C887E]"
              data-testid="tv-col-critical-overflow"
            >
              + {overflow} {overflow === 1 ? 'item' : 'itens'}
            </li>
          )}
        </ul>
      )}
    </div>
  );
}

/**
 * Mini-feed "AGORA": últimas {@link TV_MINI_FEED_SIZE} movimentações de
 * hoje (HH:MM ↗/↘ qtd× produto). Vazio → texto explícito.
 */
export function TvColumnFeed({ moves }: { moves: TvRecentMove[] }) {
  const visible = moves.slice(0, TV_MINI_FEED_SIZE);
  return (
    <div className="mt-3" data-testid="tv-col-feed">
      <TvColumnLabel>AGORA</TvColumnLabel>
      {visible.length === 0 ? (
        <p
          className="mt-1 font-momma text-[clamp(0.75rem,0.85vw,1.5rem)] text-[#7C887E]"
          data-testid="tv-col-feed-empty"
        >
          sem movimentações hoje
        </p>
      ) : (
        <ul className="mt-1 space-y-1">
          {visible.map((m, i) => (
            <li
              key={`${m.timestamp ?? 'sem-ts'}-${m.produtoNome}-${i}`}
              className="flex items-center gap-1.5 font-momma text-[clamp(0.75rem,0.85vw,1.5rem)] leading-tight"
              data-testid="tv-col-feed-item"
            >
              <span className="shrink-0 font-medium text-[#7C887E] tabular-nums">
                {m.hora}
              </span>
              {m.tipo === 'entrada' ? (
                <ArrowUpRight
                  className="h-[1em] w-[1em] shrink-0 text-[#57715B]"
                  aria-hidden
                />
              ) : (
                <ArrowDownRight
                  className="h-[1em] w-[1em] shrink-0 text-[#7C887E]"
                  aria-hidden
                />
              )}
              <span className="min-w-0 flex-1 truncate text-[#2D362E]">
                {formatQty(m.quantidade)}× {m.produtoNome}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/**
 * @module features/tv-dashboard/ui/TvChips
 *
 * Blocos visuais compartilhados do Painel TV: chip de delta semanal,
 * chip de fonte (ao vivo / atrasado / defasado Linx), chip de estado RAG,
 * badge de estoque e barra de % meta com tick de esperado.
 * Linguagem v2 (glassmorphism Momma): design.md §1.3–§1.6, §3 e §4.
 * v2.1: tipografia fluida clamp() (referência a 1920px) e ícones em `em`
 * (escalam junto com o texto do chip).
 */

import {
  ArrowDown,
  ArrowUp,
  CalendarClock,
  Check,
  OctagonAlert,
  RefreshCw,
  TriangleAlert,
} from 'lucide-react';
import type {
  TvFreshnessLevel,
  TvRagStatus,
  TvSalesChannel,
  TvStockAlertSummary,
} from '../model/types';
import { formatLaggedDateLabel } from '../model/tvMath';
import { clampPct, formatDeltaPct, type TvBarColor } from './tvFormat';

// ─────────────────────────────────────────────────────────────────────────────
// Delta comparativo (v3: principal = vs ONTEM; rótulo da base é genérico)
// ─────────────────────────────────────────────────────────────────────────────

interface TvDeltaChipProps {
  /** Delta % vs a base comparada. */
  delta: number;
  /** Rótulo da base comparada ("ontem", "dia ant.", "qua."). */
  label: string;
  /** Tamanho: hero (referência 28px a 1920px) ou card de loja (24px a 1920px). */
  size: 'hero' | 'card';
}

/**
 * Chip de delta comparativo. Neutro (pill sage suave) sempre — exceto delta
 * ≤ −15%, que vira âmbar (design.md §3 zona 1). Positivo nunca ganha verde.
 */
export function TvDeltaChip({ delta, label, size }: TvDeltaChipProps) {
  const isAlert = delta <= -15;
  const colorCls = isAlert
    ? 'bg-amber-50 text-amber-600'
    : 'bg-[#57715B]/8 text-[#5F6F63]';
  const textCls =
    size === 'hero'
      ? 'text-[clamp(0.875rem,1.45vw,2.625rem)]'
      : 'text-[clamp(0.8125rem,1.25vw,2.25rem)]';
  const Icon = delta < 0 ? ArrowDown : ArrowUp;
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1 font-momma font-medium tabular-nums leading-none lg:px-4 lg:py-1.5 ${textCls} ${colorCls}`}
      data-testid="tv-delta-chip"
    >
      <Icon className="h-[1em] w-[1em] shrink-0" aria-hidden />
      {formatDeltaPct(delta)} vs {label}
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Chip de fonte (freshness honesta — design.md §4 item 1)
// ─────────────────────────────────────────────────────────────────────────────

interface TvSourceChipProps {
  channel: TvSalesChannel;
  /** Freshness da fonte live (ignorado para canal Linx). */
  liveLevel: TvFreshnessLevel;
  /** Dia de referência (YYYY-MM-DD) do dado defasado Linx, ou null. */
  laggedDate?: string | null;
}

/**
 * Chip de fonte do card: Degust fresco → "✓ ao vivo" (emerald); Degust
 * atrasado → "⟳ atrasado" (âmbar); Linx → selo NEUTRO "até DD/MM"
 * (defasagem esperada não é alarme).
 */
export function TvSourceChip({ channel, liveLevel, laggedDate }: TvSourceChipProps) {
  if (channel === 'linx-lagged') {
    return (
      <span
        className="inline-flex items-center gap-1.5 rounded-full bg-[#57715B]/8 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-[#5F6F63]"
        data-testid="tv-source-chip-lagged"
      >
        <CalendarClock className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
        {laggedDate ? formatLaggedDateLabel(laggedDate) : 'sem dados'}
      </span>
    );
  }
  if (liveLevel === 'fresh') {
    return (
      <span
        className="inline-flex items-center gap-1.5 rounded-full bg-emerald-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-emerald-600"
        data-testid="tv-source-chip-live"
      >
        <Check className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
        ao vivo
      </span>
    );
  }
  return (
    <span
      className="inline-flex items-center gap-1.5 rounded-full border border-amber-400/40 bg-amber-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-amber-600"
      data-testid="tv-source-chip-stale"
    >
      <RefreshCw className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
      atrasado
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Chip de estado RAG (redundância não-cromática lível a 3m)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Chip "⚠ ATENÇÃO" / "⛔ CRÍTICO" do header do card. Nulo em estado ok.
 * Tem variantes dark (badge do design system) porque também é usado no
 * drill-down `/tv/loja/:id`, que roda DENTRO do DashboardLayout (tema livre).
 */
export function TvStateChip({ rag }: { rag: TvRagStatus }) {
  if (rag === 'ok') return null;
  if (rag === 'red') {
    return (
      <span
        className="inline-flex items-center gap-1.5 rounded-full bg-red-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-red-600 dark:bg-red-900/20"
        data-testid="tv-state-chip-red"
      >
        <OctagonAlert className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
        CRÍTICO
      </span>
    );
  }
  return (
    <span
      className="inline-flex items-center gap-1.5 rounded-full bg-amber-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-amber-600 dark:bg-amber-900/20"
      data-testid="tv-state-chip-amber"
    >
      <TriangleAlert className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
      ATENÇÃO
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Badge de estoque (contagem; vermelho absorve âmbar quando há ambos)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Badge de alerta de estoque do header. Se houver zerados E abaixo do
 * mínimo, mostra só o vermelho com a SOMA (design.md §4 item 1).
 */
export function TvStockBadge({ estoque }: { estoque: TvStockAlertSummary }) {
  const total = estoque.zerados + estoque.abaixoMinimo;
  if (total === 0) return null;
  if (estoque.zerados > 0) {
    return (
      <span
        className="inline-flex items-center gap-1.5 rounded-full bg-red-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-red-600 tabular-nums"
        data-testid="tv-stock-badge-red"
      >
        <OctagonAlert className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
        {total}
      </span>
    );
  }
  return (
    <span
      className="inline-flex items-center gap-1.5 rounded-full bg-amber-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-amber-600 tabular-nums"
      data-testid="tv-stock-badge-amber"
    >
      <TriangleAlert className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
      {total}
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Barra de % meta com tick de "esperado agora"
// ─────────────────────────────────────────────────────────────────────────────

const BAR_FILL_CLS: Record<TvBarColor, string> = {
  sage: 'bg-gradient-to-r from-[#57715B] to-[#4a6250]',
  amber: 'bg-gradient-to-r from-amber-400 to-amber-500',
  red: 'bg-gradient-to-r from-red-400 to-red-500',
};

interface TvMetaBarProps {
  /** % do dia COMPLETO da meta já atingido (preenchimento), ou null. */
  fillPct: number | null;
  /** Posição do tick de "esperado agora" (0–100), ou null para ocultar. */
  expectedPct: number | null;
  /** Cor semântica do preenchimento (estado de venda — design.md §1.6). */
  color: TvBarColor;
  /** Altura da barra: hero 14→20px, card 10→12px (mobile → lg+). */
  size: 'hero' | 'card';
}

/**
 * Barra horizontal de % meta: trilha sage suave (`#57715B/10`),
 * preenchimento em gradiente por estado de venda e tick DOURADO de
 * "esperado agora" (pró-rata). Transição de width 600ms ease-out (§8.1.3).
 */
export function TvMetaBar({ fillPct, expectedPct, color, size }: TvMetaBarProps) {
  const heightCls = size === 'hero' ? 'h-3.5 lg:h-5' : 'h-2.5 lg:h-3';
  const tick =
    size === 'hero'
      ? { width: 3, height: 28, offset: -4 }
      : { width: 2, height: 20, offset: -4 };
  return (
    <div
      className={`relative w-full rounded-full bg-[#57715B]/10 ${heightCls}`}
      data-testid="tv-meta-bar"
    >
      {fillPct != null && (
        <div
          className={`absolute inset-y-0 left-0 rounded-full transition-[width] [transition-duration:600ms] ease-out motion-reduce:transition-none ${BAR_FILL_CLS[color]}`}
          style={{ width: `${clampPct(fillPct)}%` }}
          data-testid="tv-meta-bar-fill"
        />
      )}
      {expectedPct != null && (
        <div
          className="absolute rounded-full bg-[#C5A065]"
          style={{
            left: `calc(${clampPct(expectedPct)}% - ${tick.width / 2}px)`,
            top: tick.offset,
            width: tick.width,
            height: tick.height,
          }}
          data-testid="tv-meta-bar-tick"
        />
      )}
    </div>
  );
}

