file.content:
/*
 * Animações do Painel TV (/tv) — lista FECHADA do design.md §8.1 (v2) —
 * mais o viewport-lock responsivo (v2.1). Só transform/opacity nas
 * animações (pixel-shift anti burn-in, fades, dots) — nenhuma cor vive
 * aqui. Importado apenas por TvDashboard.page.tsx; nada vaza para o
 * design system.
 */

/*
 * v2.1 — viewport-lock de TV/monitor grande (design.md §2).
 * O painel é uma página fluida normal (scroll natural em telas menores).
 * Quando a viewport tem largura ≥1280px E altura ≥1000px (TV 1080p+,
 * monitores grandes, kiosk fullscreen), o conteúdo TRAVA na viewport:
 * zero scroll, linha de lojas absorve a altura restante. A condição de
 * altura é essencial: em 1366×768 ou janela desktop não-maximizada o
 * conteúdo NÃO cabe e deve fluir — travar clipparia cards.
 */
@media (min-width: 1280px) and (min-height: 1000px) {
  .tv-lock-viewport {
    height: 100dvh;
    overflow: hidden;
  }

  .tv-lock-fill {
    height: 100%;
  }

  .tv-lock-grow {
    flex: 1 1 0%;
    min-height: 0;
  }
}

@media (prefers-reduced-motion: no-preference) {
  /* §8.1.5 — pixel-shift anti burn-in: ciclo de 16 min (960s), passos de
     1-2px com interpolação de ~2s (0.2% de 960s ≈ 1,9s) em cada troca. */
  @keyframes tv-pixel-shift {
    0% {
      transform: translate(0, 0);
    }
    24.8% {
      transform: translate(0, 0);
    }
    25% {
      transform: translate(1px, 1px);
    }
    49.8% {
      transform: translate(1px, 1px);
    }
    50% {
      transform: translate(0, 2px);
    }
    74.8% {
      transform: translate(0, 2px);
    }
    75% {
      transform: translate(-1px, 1px);
    }
    99.8% {
      transform: translate(-1px, 1px);
    }
    100% {
      transform: translate(0, 0);
    }
  }

  .tv-pixel-shift {
    animation: tv-pixel-shift 960s ease-in-out infinite;
  }

  /* §8.1.2 — fade-in de exceção nova (uma única vez) */
  @keyframes tv-fade-in {
    from {
      opacity: 0;
      transform: translateY(6px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  .tv-fade-in {
    animation: tv-fade-in 300ms ease-out both;
  }

  /* §7 — conteúdo entra com fade único de 300ms após o primeiro load */
  @keyframes tv-content-enter {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }

  .tv-content-enter {
    animation: tv-content-enter 300ms ease-out both;
  }

  /* §7 — loading inicial: 3 pontos que acendem em sequência (1×/600ms),
     único movimento permitido fora do estado carregado. */
  @keyframes tv-dot {
    0%,
    100% {
      opacity: 0.2;
    }
    33% {
      opacity: 1;
    }
  }

  .tv-dot {
    animation: tv-dot 1800ms steps(3, jump-none) infinite;
  }

  .tv-dot:nth-child(2) {
    animation-delay: 600ms;
  }

  .tv-dot:nth-child(3) {
    animation-delay: 1200ms;
  }
}

/* §8.1.3/§8.1.4 — transições de barra e de estado RAG valem mesmo com
   reduced-motion? Não: §8.1.7 manda trocar seco. As classes utilitárias de
   transição são aplicadas via Tailwind nos componentes; aqui apenas as
   desligamos sob reduced-motion. */
@media (prefers-reduced-motion: reduce) {
  .tv-pixel-shift,
  .tv-fade-in,
  .tv-content-enter,
  .tv-dot {
    animation: none;
  }
}

