/**
 * @module features/pronta-entrega/ui/SaldosList
 *
 * Lista unificada de saldos (câmara fria × expositora) — presentational.
 * Desktop: tabela Produto | Estoque | Expositora | Total | ações.
 * Mobile: cards empilhados com os 3 números visíveis sem scroll horizontal.
 * Expositora negativa: vermelho + ícone de alerta + tooltip de recontagem.
 */

import { AlertTriangle, ArrowRightToLine, SlidersHorizontal } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { GlassCard } from '@/shared/ui/glass-card';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/shared/ui/tooltip';
import { cn } from '@/shared/lib/utils';
import type { SaldoRow } from '../model/saldos';

const NEGATIVE_HINT =
  'Vendeu/perdeu mais do que foi registrado na vitrine — faça uma recontagem';

interface SaldosListProps {
  rows: SaldoRow[];
  onExpor: (row: SaldoRow) => void;
  onAjustar: (row: SaldoRow) => void;
}

function ExpositoraValue({ row }: { row: SaldoRow }) {
  const negativo = row.expositora < 0;

  if (!negativo) {
    return (
      <span
        data-testid={`expositora-${row.produtoId}`}
        className="font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF]"
      >
        {row.expositora}
      </span>
    );
  }

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <span
          data-testid={`expositora-${row.produtoId}`}
          className="inline-flex items-center gap-1 font-bold tabular-nums text-red-600 dark:text-red-400"
        >
          <AlertTriangle className="w-3.5 h-3.5 shrink-0" aria-label="Saldo negativo" />
          {row.expositora}
        </span>
      </TooltipTrigger>
      <TooltipContent className="max-w-[260px] text-center">{NEGATIVE_HINT}</TooltipContent>
    </Tooltip>
  );
}

function RowActions({
  row,
  onExpor,
  onAjustar,
  className,
}: {
  row: SaldoRow;
  onExpor: (row: SaldoRow) => void;
  onAjustar: (row: SaldoRow) => void;
  className?: string;
}) {
  return (
    <div className={cn('flex items-center gap-2', className)}>
      <Button
        size="sm"
        data-mia-action="expor-produto"
        onClick={() => onExpor(row)}
        disabled={row.estoque <= 0}
        className="h-9 flex-1 sm:flex-none rounded-xl bg-[#57715B] hover:bg-[#465b49] text-white font-bold shadow-sm shadow-[#57715B]/20"
      >
        <ArrowRightToLine className="w-4 h-4 mr-1.5" /> Expor
      </Button>
      <Button
        size="sm"
        variant="outline"
        data-mia-action="ajustar-expositora"
        onClick={() => onAjustar(row)}
        className="h-9 flex-1 sm:flex-none rounded-xl border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 font-bold"
      >
        <SlidersHorizontal className="w-4 h-4 mr-1.5" /> Ajustar
      </Button>
    </div>
  );
}

/**
 * Lista responsiva dos saldos unificados, com ações Expor/Ajustar por linha.
 */
export function SaldosList({ rows, onExpor, onAjustar }: SaldosListProps) {
  return (
    <>
      {/* Desktop: tabela */}
      <GlassCard className="hidden md:block overflow-hidden" gradient={false}>
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-[#57715B]/5 border-b border-[#57715B]/10 text-left">
              <th className="px-5 py-3 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                Produto
              </th>
              <th className="px-5 py-3 text-xs font-semibold uppercase tracking-wider text-muted-foreground text-right">
                Estoque
              </th>
              <th className="px-5 py-3 text-xs font-semibold uppercase tracking-wider text-muted-foreground text-right">
                Expositora
              </th>
              <th className="px-5 py-3 text-xs font-semibold uppercase tracking-wider text-muted-foreground text-right">
                Total
              </th>
              <th className="px-5 py-3 text-xs font-semibold uppercase tracking-wider text-muted-foreground text-right">
                Ações
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr
                key={row.produtoId}
                className="border-b border-[#57715B]/5 last:border-0 hover:bg-white/80 dark:hover:bg-[#1A1A1A]/80 transition-colors"
              >
                <td className="px-5 py-3">
                  <div className="font-bold text-[#2D362E] dark:text-[#E6DCCF]">{row.nome}</div>
                  {row.setor && (
                    <div className="text-[11px] text-muted-foreground">{row.setor}</div>
                  )}
                </td>
                <td className="px-5 py-3 text-right font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF]">
                  {row.estoque}
                </td>
                <td className="px-5 py-3 text-right">
                  <ExpositoraValue row={row} />
                </td>
                <td className="px-5 py-3 text-right font-bold tabular-nums text-[#57715B] dark:text-[#8FAE94]">
                  {row.total}
                </td>
                <td className="px-5 py-3">
                  <RowActions row={row} onExpor={onExpor} onAjustar={onAjustar} className="justify-end" />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </GlassCard>

      {/* Mobile: cards empilhados */}
      <div className="md:hidden space-y-2">
        {rows.map((row) => (
          <GlassCard key={row.produtoId} className="p-3" gradient={false}>
            <div className="mb-2">
              <div className="font-bold text-sm leading-snug text-[#2D362E] dark:text-[#E6DCCF] break-words">
                {row.nome}
              </div>
              {row.setor && (
                <div className="text-[10px] uppercase tracking-wider text-muted-foreground">
                  {row.setor}
                </div>
              )}
            </div>
            <div className="grid grid-cols-3 gap-2 mb-3">
              <div className="rounded-xl bg-white/60 dark:bg-white/5 border border-[#57715B]/10 px-2 py-1.5 text-center">
                <div className="text-[9px] font-semibold uppercase tracking-wider text-muted-foreground">
                  Estoque
                </div>
                <div className="text-base font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF]">
                  {row.estoque}
                </div>
              </div>
              <div
                className={cn(
                  'rounded-xl border px-2 py-1.5 text-center',
                  row.expositora < 0
                    ? 'bg-red-50 dark:bg-red-900/20 border-red-200 dark:border-red-900/40'
                    : 'bg-white/60 dark:bg-white/5 border-[#57715B]/10',
                )}
              >
                <div className="text-[9px] font-semibold uppercase tracking-wider text-muted-foreground">
                  Expositora
                </div>
                <div className="text-base">
                  <ExpositoraValue row={row} />
                </div>
              </div>
              <div className="rounded-xl bg-[#57715B]/5 border border-[#57715B]/10 px-2 py-1.5 text-center">
                <div className="text-[9px] font-semibold uppercase tracking-wider text-muted-foreground">
                  Total
                </div>
                <div className="text-base font-bold tabular-nums text-[#57715B] dark:text-[#8FAE94]">
                  {row.total}
                </div>
              </div>
            </div>
            <RowActions row={row} onExpor={onExpor} onAjustar={onAjustar} />
          </GlassCard>
        ))}
      </div>
    </>
  );
}

