1	/**
2	 * @module features/pronta-entrega/ui/ProntaEntrega.page
3	 *
4	 * Pronta Entrega v2 — saldo unificado da loja: câmara fria (`estoque`) ×
5	 * expositora/vitrine (`expositora_estoque`), com movimentação atômica pra
6	 * vitrine, ajustes com motivo, contagem guiada e histórico (ledger).
7	 * Fábrica (loja_id=1) não tem expositora — mostra empty state.
8	 */
9	
10	import { useCallback, useMemo, useRef, useState } from 'react';
11	import {
12	  AlertTriangle,
13	  ClipboardList,
14	  Factory,
15	  History,
16	  Monitor,
17	  PackageOpen,
18	  RotateCw,
19	  Search,
20	  Snowflake,
21	  Store,
22	} from 'lucide-react';
23	import { toast } from 'sonner';
24	import { Button } from '@/shared/ui/button';
25	import { Input } from '@/shared/ui/input';
26	import {
27	  Select,
28	  SelectContent,
29	  SelectItem,
30	  SelectTrigger,
31	  SelectValue,
32	} from '@/shared/ui/select';
33	import { Skeleton } from '@/shared/ui/skeleton';
34	import { GlassCard } from '@/shared/ui/glass-card';
35	import { MommaPageLayout } from '@/shared/ui/MommaPageLayout';
36	import { PermissionBlur } from '@/shared/ui/PermissionBlur';
37	import { usePermissions } from '@/shared/hooks/usePermissions';
38	import { useStore } from '@/shared/contexts/StoreContext';
39	import { cn } from '@/shared/lib/utils';
40	import { useMiaPageContext } from '@/features/mia/hooks/useMiaPageContext';
41	import { useMiaProntaEntregaActions } from '@/features/mia/model/hooks';
42	import {
43	  FABRICA_LOJA_ID,
44	  filterSaldos,
45	  normalizeSearchText,
46	  type SaldoRow,
47	} from '../model/saldos';
48	import { useProntaEntregaSaldos } from '../model/useProntaEntregaSaldos';
49	import { useExpositoraMutations } from '../model/useExpositoraMutations';
50	import { SaldosList } from './SaldosList';
51	import { MoverParaExpositoraModal } from './MoverParaExpositoraModal';
52	import { AjusteExpositoraModal, type AjusteSubmit } from './AjusteExpositoraModal';
53	import { ContagemExpositoraSheet, type ContagemEntry } from './ContagemExpositoraSheet';
54	import { HistoricoExpositoraSheet } from './HistoricoExpositoraSheet';
55	
56	export default function ProntaEntregaPage() {
57	  useMiaPageContext({
58	    description:
59	      'Pronta Entrega — saldo da câmara fria (estoque) e da expositora/vitrine por loja. Permite expor produto na vitrine, ajustar saldo com motivo, fazer contagem guiada e ver o histórico (ledger).',
60	    natural_language_hints:
61	      '"expor X" / "colocar X na vitrine" = botão Expor (mover_para_expositora); "ajustar X" / "perda/vencido/degustação" = botão Ajustar (ajustar_expositora); "recontagem" / "contagem" = botão Contagem; "histórico da vitrine" = botão Histórico; saldo negativo na expositora = furo de processo, recomendar recontagem.',
62	    capabilities: [
63	      'consultar_saldos',
64	      'expor_na_vitrine',
65	      'ajustar_expositora',
66	      'contagem_guiada',
67	      'historico',
68	    ],
69	    destructive_actions: ['ajustar_expositora', 'aplicar_contagem'],
70	    primary_entity: 'expositora_estoque',
71	  });
72	
73	  const { canViewProntaEntrega, isAdmin } = usePermissions();
74	  const { selectedStore, stores } = useStore();
75	
76	  // Admin pode olhar outra loja sem trocar a loja global; usuário comum usa a própria
77	  const [storeOverride, setStoreOverride] = useState<number | null>(null);
78	  const lojaId = (isAdmin() ? storeOverride : null) ?? selectedStore?.id ?? null;
79	  const isFabrica = lojaId === FABRICA_LOJA_ID;
80	
81	  const [search, setSearch] = useState('');
82	  const [exporProduto, setExporProduto] = useState<SaldoRow | null>(null);
83	  const [ajusteProduto, setAjusteProduto] = useState<SaldoRow | null>(null);
84	  const [contagemOpen, setContagemOpen] = useState(false);
85	  const [historicoOpen, setHistoricoOpen] = useState(false);
86	  const [contagemPending, setContagemPending] = useState(false);
87	
88	  const { rows, isLoading, isError, refetch } = useProntaEntregaSaldos(lojaId);
89	  const { mover, ajustar } = useExpositoraMutations(lojaId);
90	
91	  const filtered = useMemo(() => filterSaldos(rows, search), [rows, search]);
92	
93	  const kpis = useMemo(() => {
94	    let totalEstoque = 0;
95	    let totalExpositora = 0;
96	    let negativos = 0;
97	    for (const row of rows) {
98	      totalEstoque += row.estoque;
99	      totalExpositora += row.expositora;
100	      if (row.expositora < 0) negativos += 1;
101	    }
102	    return { totalEstoque, totalExpositora, negativos };
103	  }, [rows]);
104	
105	  // ── MIA: callbacks estáveis (handlers são registrados uma única vez) ──
106	  const rowsRef = useRef<SaldoRow[]>(rows);
107	  rowsRef.current = rows;
108	
109	  const miaRefetch = useCallback(() => {
110	    void refetch();
111	  }, [refetch]);
112	
113	  const miaOpenExporModal = useCallback((productName?: string) => {
114	    if (!productName) {
115	      const first = rowsRef.current[0] ?? null;
116	      if (first) setExporProduto(first);
117	      else toast.error('Nenhum produto com saldo pra expor nesta loja.');
118	      return;
119	    }
120	    const term = normalizeSearchText(productName);
121	    const match = rowsRef.current.find((r) => normalizeSearchText(r.nome).includes(term));
122	    if (match) setExporProduto(match);
123	    else toast.error(`Produto "${productName}" não encontrado na lista da loja.`);
124	  }, []);
125	
126	  useMiaProntaEntregaActions({
127	    setSearch,
128	    refetch: miaRefetch,
129	    openExporModal: miaOpenExporModal,
130	  });
131	
132	  // ── Handlers das mutations (erros já viram toast no hook) ──
133	  const handleExporConfirm = async (quantidade: number, observacoes?: string) => {
134	    if (!exporProduto) return;
135	    try {
136	      await mover.mutateAsync({ produtoId: exporProduto.produtoId, quantidade, observacoes });
137	      toast.success(`${quantidade}× ${exporProduto.nome} movido pra expositora.`);
138	      setExporProduto(null);
139	    } catch {
140	      // erro já exibido via toast no hook de mutation
141	    }
142	  };
143	
144	  const handleAjusteConfirm = async (input: AjusteSubmit) => {
145	    if (!ajusteProduto) return;
146	    try {
147	      const result = await ajustar.mutateAsync({
148	        produtoId: ajusteProduto.produtoId,
149	        ...input,
150	      });
151	      toast.success(
152	        `Expositora de ${ajusteProduto.nome} ajustada: ${result.saldo_anterior ?? '?'} → ${result.saldo ?? '?'}.`,
153	      );
154	      setAjusteProduto(null);
155	    } catch {
156	      // erro já exibido via toast no hook de mutation
157	    }
158	  };
159	
160	  const handleContagemConfirm = async (entries: ContagemEntry[]) => {
161	    // Loja inteira zerada na expositora = primeira contagem
162	    const motivo = rows.every((r) => r.expositora === 0) ? 'contagem_inicial' : 'recontagem';
163	    setContagemPending(true);
164	    let aplicados = 0;
165	    let falhas = 0;
166	    for (const entry of entries) {
167	      try {
168	        await ajustar.mutateAsync({
169	          produtoId: entry.produtoId,
170	          quantidade: entry.quantidade,
171	          modo: 'absoluto',
172	          motivo,
173	        });
174	        aplicados += 1;
175	      } catch {
176	        falhas += 1;
177	      }
178	    }
179	    setContagemPending(false);
180	    if (aplicados > 0) {
181	      toast.success(`Contagem aplicada em ${aplicados} produto${aplicados === 1 ? '' : 's'}.`);
182	    }
183	    if (falhas > 0) {
184	      toast.error(`${falhas} produto${falhas === 1 ? '' : 's'} falharam na contagem.`);
185	    } else {
186	      setContagemOpen(false);
187	    }
188	  };
189	
190	  const acoesDisponiveis = lojaId !== null && !isFabrica;
191	
192	  return (
193	    <PermissionBlur hasPermission={canViewProntaEntrega()} moduleName="Pronta Entrega">
194	      <MommaPageLayout>
195	        <div
196	          data-mia-page="pronta-entrega"
197	          data-mia-domain="estoque"
198	          className="flex-1 w-full max-w-[1400px] mx-auto px-4 md:px-8 pt-8 md:pt-10 pb-10 space-y-5 md:space-y-6"
199	        >
200	          {/* Header */}
201	          <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
202	            <div className="flex items-center gap-3">
203	              <div className="p-2.5 rounded-2xl bg-[#57715B]/10 shrink-0">
204	                <Monitor className="w-6 h-6 text-[#57715B]" />
205	              </div>
206	              <div>
207	                <h1 className="text-2xl md:text-4xl font-bold tracking-tight font-serif text-[#2D362E] dark:text-[#E6DCCF] leading-none">
208	                  Pronta Entrega
209	                </h1>
210	                <p className="text-[10px] md:text-xs uppercase tracking-widest text-[#57715B] dark:text-[#8FAE94] font-bold opacity-80 mt-1.5">
211	                  Câmara fria × expositora da loja
212	                </p>
213	              </div>
214	            </div>
215	
216	            <div className="flex flex-wrap items-center gap-2">
217	              {isAdmin() && (
218	                <Select
219	                  value={lojaId !== null ? String(lojaId) : undefined}
220	                  onValueChange={(v) => setStoreOverride(Number(v))}
221	                >
222	                  <SelectTrigger
223	                    className="h-10 w-[170px] rounded-xl border border-[#57715B]/20 bg-white/60 dark:bg-zinc-800/40 backdrop-blur-sm text-xs font-medium"
224	                    data-mia-filter="loja"
225	                    data-mia-options={stores.map((s) => s.name).join(',')}
226	                  >
227	                    <Store className="w-3.5 h-3.5 mr-1.5 text-[#57715B] shrink-0" />
228	                    <SelectValue placeholder="Loja" />
229	                  </SelectTrigger>
230	                  <SelectContent>
231	                    {stores.map((store) => (
232	                      <SelectItem key={store.id} value={String(store.id)}>
233	                        {store.name}
234	                      </SelectItem>
235	                    ))}
236	                  </SelectContent>
237	                </Select>
238	              )}
239	              <Button
240	                variant="outline"
241	                data-mia-action="abrir-contagem"
242	                data-mia-expects-modal-open="contagem-expositora"
243	                onClick={() => setContagemOpen(true)}
244	                disabled={!acoesDisponiveis}
245	                className="h-10 rounded-xl border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 font-bold bg-white/60 dark:bg-zinc-800/40 backdrop-blur-sm"
246	              >
247	                <ClipboardList className="w-4 h-4 sm:mr-1.5" />
248	                <span className="hidden sm:inline">Contagem</span>
249	              </Button>
250	              <Button
251	                variant="outline"
252	                data-mia-action="abrir-historico"
253	                data-mia-expects-modal-open="historico-expositora"
254	                onClick={() => setHistoricoOpen(true)}
255	                disabled={!acoesDisponiveis}
256	                className="h-10 rounded-xl border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 font-bold bg-white/60 dark:bg-zinc-800/40 backdrop-blur-sm"
257	              >
258	                <History className="w-4 h-4 sm:mr-1.5" />
259	                <span className="hidden sm:inline">Histórico</span>
260	              </Button>
261	            </div>
262	          </div>
263	
264	          {isFabrica ? (
265	            // Empty state: Fábrica não tem expositora
266	            <GlassCard className="p-8 md:p-12 text-center" variant="premium">
267	              <Factory className="w-12 h-12 mx-auto text-[#57715B]/40 mb-4" />
268	              <h2 className="text-lg md:text-xl font-serif font-bold text-[#2D362E] dark:text-[#E6DCCF]">
269	                A Fábrica não tem expositora
270	              </h2>
271	              <p className="text-sm text-muted-foreground mt-2 max-w-md mx-auto">
272	                A expositora é a vitrine/balcão de cada loja. Selecione uma loja pra ver e
273	                movimentar os saldos de pronta entrega.
274	              </p>
275	            </GlassCard>
276	          ) : (
277	            <>
278	              {/* KPIs compactos */}
279	              <div className="grid grid-cols-3 gap-2 md:gap-4">
280	                <div className="relative overflow-hidden group rounded-2xl md:rounded-[2rem] border border-[#57715B]/10 bg-white/60 dark:bg-[#1A1A1A]/60 backdrop-blur-md shadow-sm hover:shadow-md p-3 md:p-5">
281	                  <Snowflake className="absolute top-1 right-1 w-10 h-10 md:w-16 md:h-16 text-[#57715B] opacity-10 group-hover:opacity-20 transition-opacity" />
282	                  <div className="text-[9px] md:text-xs font-semibold uppercase tracking-wider text-muted-foreground">
283	                    Na câmara
284	                  </div>
285	                  <div className="text-xl md:text-2xl font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF]">
286	                    {isLoading ? '—' : kpis.totalEstoque}
287	                  </div>
288	                </div>
289	                <div className="relative overflow-hidden group rounded-2xl md:rounded-[2rem] border border-[#57715B]/10 bg-white/60 dark:bg-[#1A1A1A]/60 backdrop-blur-md shadow-sm hover:shadow-md p-3 md:p-5">
290	                  <Monitor className="absolute top-1 right-1 w-10 h-10 md:w-16 md:h-16 text-[#57715B] opacity-10 group-hover:opacity-20 transition-opacity" />
291	                  <div className="text-[9px] md:text-xs font-semibold uppercase tracking-wider text-muted-foreground">
292	                    Na expositora
293	                  </div>
294	                  <div className="text-xl md:text-2xl font-bold tabular-nums text-[#57715B] dark:text-[#8FAE94]">
295	                    {isLoading ? '—' : kpis.totalExpositora}
296	                  </div>
297	                </div>
298	                <div
299	                  className={cn(
300	                    'relative overflow-hidden group rounded-2xl md:rounded-[2rem] border backdrop-blur-md shadow-sm hover:shadow-md p-3 md:p-5',
301	                    kpis.negativos > 0
302	                      ? 'border-red-200 dark:border-red-900/40 bg-red-50/60 dark:bg-red-900/10'
303	                      : 'border-[#57715B]/10 bg-white/60 dark:bg-[#1A1A1A]/60',
304	                  )}
305	                >
306	                  <AlertTriangle
307	                    className={cn(
308	                      'absolute top-1 right-1 w-10 h-10 md:w-16 md:h-16 opacity-10 group-hover:opacity-20 transition-opacity',
309	                      kpis.negativos > 0 ? 'text-red-600' : 'text-[#57715B]',
310	                    )}
311	                  />
312	                  <div className="text-[9px] md:text-xs font-semibold uppercase tracking-wider text-muted-foreground">
313	                    Negativos
314	                  </div>
315	                  <div
316	                    className={cn(
317	                      'text-xl md:text-2xl font-bold tabular-nums',
318	                      kpis.negativos > 0
319	                        ? 'text-red-600 dark:text-red-400'
320	                        : 'text-[#2D362E] dark:text-[#E6DCCF]',
321	                    )}
322	                  >
323	                    {isLoading ? '—' : kpis.negativos}
324	                  </div>
325	                </div>
326	              </div>
327	
328	              {/* Busca */}
329	              <div className="relative w-full md:max-w-sm">
330	                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
331	                <Input
332	                  data-mia-field="busca-produto"
333	                  placeholder="Buscar produto..."
334	                  value={search}
335	                  onChange={(e) => setSearch(e.target.value)}
336	                  className="pl-9 h-11 rounded-xl bg-white/60 dark:bg-zinc-800/40 border-[#57715B]/10 backdrop-blur-sm"
337	                />
338	              </div>
339	
340	              {/* Lista / estados */}
341	              {isLoading ? (
342	                <div className="space-y-2">
343	                  {[1, 2, 3, 4, 5].map((i) => (
344	                    <Skeleton key={i} className="h-[88px] md:h-14 rounded-2xl" />
345	                  ))}
346	                </div>
347	              ) : isError ? (
348	                <GlassCard className="p-8 text-center" gradient={false}>
349	                  <AlertTriangle className="w-10 h-10 mx-auto text-red-500/60 mb-3" />
350	                  <p className="font-bold text-[#2D362E] dark:text-[#E6DCCF]">
351	                    Erro ao carregar os saldos
352	                  </p>
353	                  <p className="text-sm text-muted-foreground mt-1">
354	                    Verifique a conexão e tente de novo.
355	                  </p>
356	                  <Button
357	                    data-mia-action="tentar-novamente"
358	                    onClick={() => void refetch()}
359	                    className="mt-4 h-10 rounded-xl bg-[#57715B] hover:bg-[#465b49] text-white font-bold"
360	                  >
361	                    <RotateCw className="w-4 h-4 mr-2" /> Tentar novamente
362	                  </Button>
363	                </GlassCard>
364	              ) : rows.length === 0 ? (
365	                <GlassCard className="p-8 md:p-12 text-center" gradient={false}>
366	                  <PackageOpen className="w-12 h-12 mx-auto text-[#57715B]/30 mb-4" />
367	                  <p className="font-serif font-bold text-lg text-[#2D362E] dark:text-[#E6DCCF]">
368	                    Nenhum produto com saldo
369	                  </p>
370	                  <p className="text-sm text-muted-foreground mt-2 max-w-md mx-auto">
371	                    Quando a loja receber produtos na câmara fria ou registrar itens na
372	                    expositora, eles aparecem aqui.
373	                  </p>
