                  )}
                </td>
                <td className="px-5 py-3 text-right font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF]">
                  {row.estoque}
                </td>
                <td className="px-5 py-3 text-right">
                  <ExpositoraValue row={row} />
                </td>
                <td className="px-5 py-3">
                  <RowActions row={row} onExpor={onExpor} onAjustar={onAjustar} className="justify-end" />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </GlassCard>

      {/* Mobile: cards empilhados */}
      <div className="md:hidden space-y-2">
        {rows.map((row) => (
          <GlassCard key={row.produtoId} className="p-3" gradient={false}>
            <div className="mb-2">
              <div className="font-bold text-sm leading-snug text-[#2D362E] dark:text-[#E6DCCF] break-words">
                {row.nome}
              </div>
              {row.setor && (
                <div className="text-[10px] uppercase tracking-wider text-muted-foreground">
                  {row.setor}
                </div>
              )}
            </div>
            <div className="grid grid-cols-3 gap-2 mb-3">
              <div className="rounded-xl bg-white/60 dark:bg-white/5 border border-[#57715B]/10 px-2 py-1.5 text-center">
                <div className="text-[9px] font-semibold uppercase tracking-wider text-muted-foreground">
                  Estoque
                </div>
                <div className="text-base font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF]">
                  {row.estoque}
                </div>
              </div>
              <div
                className={cn(
                  'rounded-xl border px-2 py-1.5 text-center',
                  row.expositora < 0
                    ? 'bg-red-50 dark:bg-red-900/20 border-red-200 dark:border-red-900/40'
                    : 'bg-white/60 dark:bg-white/5 border-[#57715B]/10',
                )}
              >
                <div className="text-[9px] font-semibold uppercase tracking-wider text-muted-foreground">
                  Expositora
                </div>
                <div className="text-base">
                  <ExpositoraValue row={row} />
                </div>
              </div>
              <div className="rounded-xl bg-[#57715B]/5 border border-[#57715B]/10 px-2 py-1.5 text-center">
                <div className="text-[9px] font-semibold uppercase tracking-wider text-muted-foreground">
                  Total
                </div>
                <div className="text-base font-bold tabular-nums text-[#57715B] dark:text-[#8FAE94]">
                  {row.total}
                </div>
              </div>
            </div>
            <RowActions row={row} onExpor={onExpor} onAjustar={onAjustar} />
          </GlassCard>
        ))}
      </div>
    </>
  );
}

